"Falha ao validar o retorno do Discord. Tente de novo em alguns segundos.": "Failed to validate Discord's response. Try again in a few seconds.",
"Nenhuma conta reWork está vinculada a esse Discord. Peça pra alguém da coordenação vincular seu ID, ou entre com usuário/senha e vincule no perfil.": "No reWork account is linked to this Discord. Ask someone from coordination to link your ID, or sign in with username/password and link it in your profile.",
