"Esqueci minha senha": "I forgot my password",
"Informe o e-mail cadastrado no seu perfil. Se houver conta vinculada, vamos enviar um link para definir uma nova senha.": "Enter the email registered in your profile. If there's a linked account, we'll send a link to set a new password.",
"Enviar link": "Send link",
"Se o e-mail estiver cadastrado, você vai receber as instruções em alguns minutos. Confira também o spam.": "If the email is registered, you'll get the instructions in a few minutes. Check your spam too.",
