"Bem-vindo ao reWork": "Welcome to reWork",
"Oi {0}! Preparei um tour rápido pra você conhecer as principais áreas do sistema. Menos de 2 minutos, e você já sai pronto pra tocar seu dia.": "Hi {0}! I've prepared a quick tour so you can get to know the main areas of the system. Under 2 minutes, and you'll be ready to run your day.",
"Menu principal": "Main menu",
"Todas as áreas do sistema estão listadas aqui. Você pode compactar a sidebar clicando no ícone abaixo, e navegar rapidamente entre Início, Demandas, Análises e outros módulos.": "Every area of the system is listed here. You can compact the sidebar by clicking the icon below, and quickly move between Home, Tasks, Analytics and other modules.",
"Início — sua sala de comando": "Home — your command room",
"A tela inicial reúne tudo que você precisa saber num relance: o que tem pra hoje, o que atrasou, onde a equipe está e quais projetos estão sob risco.": "The home screen brings together everything you need to know at a glance: what's on for today, what's late, where the team is and which projects are at risk.",
"Meu foco de hoje": "My focus today",
"As demandas que precisam da sua atenção hoje. Prioridade pra fechar o dia sabendo o que realmente importa.": "The tasks that need your attention today. A priority list to close the day knowing what really matters.",
"Paradas": "Stalled",
"Demandas travadas por dependências ou pendências externas. Aqui você vê o que precisa desbloquear antes de destrancar entregas.": "Tasks blocked by dependencies or external pending items. Here you see what needs unblocking before deliveries can move.",
"Demandas previstas": "Upcoming tasks",
"Timeline dos próximos dias úteis. Alterna entre \"Previstas\" (planejadas) e \"Prazos\" (deadlines) — visão semanal do que vem por aí.": "Timeline of the next business days. Switch between \"Upcoming\" (planned) and \"Due dates\" (deadlines) — a weekly view of what's coming.",
"Radar de projetos": "Project radar",
"Panorama macro dos projetos ativos com atrasos, entregas e status. Ótimo pra reuniões rápidas de status.": "Big-picture view of active projects with delays, deliveries and status. Great for quick status meetings.",
"Demandas — visão completa": "Tasks — full view",
"Todas as demandas ativas agrupadas por urgência (atrasadas, hoje, na semana, próximos, sem prazo). Filtre, ordene e edite direto na lista.": "All active tasks grouped by urgency (overdue, today, this week, upcoming, no due date). Filter, sort and edit right in the list.",
"Minhas Demandas": "My Tasks",
"Recorte só do que é seu — o que você responde por, com prazo, cliente e projeto num só lugar. É a tela que você mais vai usar no dia a dia.": "Just what's yours — what you're responsible for, with due date, client and project in one place. It's the screen you'll use most day to day.",
"Agenda": "Schedule",
"Visualização de calendário das demandas agendadas + eventos. Arraste pra reagendar, clique pra abrir. Pode alternar entre visões pessoal e por time.": "Calendar view of scheduled tasks + events. Drag to reschedule, click to open. You can switch between personal and team views.",
"Análises — Capacidade": "Analytics — Capacity",
"Aba de Capacidade mostra distribuição de carga por pessoa, projeto ou cliente. Serve pra balancear a operação sem precisar chutar.": "The Capacity tab shows the workload distribution by person, project or client. It helps balance the operation without guesswork.",
"Análises — Ritmo": "Analytics — Rhythm",
"Burndown semanal por equipe. A linha ideal segue os prazos combinados — se a linha real fica acima dela, a equipe está atrasada. Leitura assertiva do ritmo da semana.": "Weekly burndown by team. The ideal line follows the agreed due dates — if the actual line stays above it, the team is behind. A clear read of the week's pace.",
"Todos os clientes com seus projetos, KPIs e integrações. Aqui você abre o detalhe pra criar demandas rápido, gerar relatório mensal ou compartilhar um painel público read-only.": "All clients with their projects, KPIs and integrations. Here you open the detail to create tasks quickly, generate the monthly report or share a public read-only board.",
"Criar demanda": "Create task",
"O acesso pra abrir uma nova demanda fica sempre visível no topo. Preencha em segundos: cliente, projeto, fluxo, prazo e responsável.": "The shortcut to open a new task is always visible at the top. Fill it in within seconds: client, project, workflow, due date and assignee.",
"Notificações em tempo real": "Real-time notifications",
"Menções, mudanças de etapa, atribuições e prazos chegam aqui ao vivo. O badge some quando você abre — as não clicadas seguem com fundo destacado até você entrar em cada uma.": "Mentions, stage changes, assignments and due dates arrive here live. The badge disappears when you open it — the unclicked ones keep a highlighted background until you open each one.",
"Seu perfil": "Your profile",
"Este bloco no rodapé da sidebar é o atalho pro seu perfil. Vamos entrar rapidamente pra você conhecer o que fica lá dentro.": "This block at the bottom of the sidebar is the shortcut to your profile. Let's step in quickly so you see what's inside.",
"Configurações do perfil": "Profile settings",
"Conta (seus dados e e-mail), Ausência (férias e folgas), Notificações (o que chega por e-mail e Discord), Aparência (tema e cores), Integrações (Discord e Google), Segurança (senha) e Ajuda (este tour e as novidades).": "Account (your details and email), Time off (vacations and days off), Notifications (what arrives by email and Discord), Appearance (theme and colors), Integrations (Discord and Google), Security (password) and Help (this tour and what's new).",
"Aparência": "Appearance",
"Tema claro, escuro ou automático, e a cor de destaque. A cor acompanha você em qualquer computador.": "Light, dark or automatic theme, and the accent color. The color follows you on any computer.",
"Preferências de notificação": "Notification preferences",
"O sino recebe tudo. Aqui você escolhe, aviso por aviso, o que também chega por e-mail e pelo Discord. Salva na hora.": "The bell gets everything. Here you choose, alert by alert, what also arrives by email and Discord. Saves instantly.",
"Integrações": "Integrations",
"Conecte seu Discord pra receber DM/notificação em canal e o Google Calendar pra ver seus eventos junto com as demandas.": "Connect your Discord to get DMs/channel notifications and Google Calendar to see your events alongside your tasks.",
"Ajuda": "Help",
"Refaça este tour quando quiser, veja as notas de atualização e os documentos legais. A senha e o botão de sair ficam em Segurança.": "Redo this tour whenever you like, see the release notes and the legal documents. Password and the sign-out button are under Security.",
"Atalho de superpoder": "Superpower shortcut",
"Aperte Ctrl + K a qualquer momento e você abre a paleta de comandos: navegar, criar, buscar demanda por nome, atalhos pra tudo. Vai poupar muito clique, {0}.": "Press Ctrl + K at any time to open the command palette: navigate, create, search tasks by name, shortcuts to everything. It'll save you a lot of clicks, {0}.",
"Pronto pra começar": "Ready to start",
"Foi isso! Você pode reabrir esse tour a qualquer momento pelo seu perfil. Boas demandas — e boa sorte com o time. 🚀": "That's it! You can reopen this tour anytime from your profile. Happy tasks — and good luck with the team. 🚀",
