"O Q3 fechou 18% acima do trimestre anterior em MRR, puxado por 3 grandes contas fechadas no segmento enterprise. NPS subiu 8 pontos após a entrega do novo onboarding. Principal desafio: churn na base SMB cresceu para 4.2%.": "Q3 closed 18% above the previous quarter in MRR, driven by 3 large accounts closed in the enterprise segment. NPS rose 8 points after the new onboarding shipped. Main challenge: churn in the SMB base grew to 4.2%.",
