"Novo onboarding reduziu tempo até \"primeira valor\" de 12 pra 5 dias.": "The new onboarding cut the time to \"first value\" from 12 to 5 days.",
"Campanha no LinkedIn trouxe 40% dos leads qualificados.": "The LinkedIn campaign brought in 40% of qualified leads.",
"O que precisa atenção": "What needs attention",
"Churn SMB em 4.2% — investigar drivers (feature gap? preço? suporte?).": "SMB churn at 4.2% — investigate drivers (feature gap? price? support?).",
"CAC subiu 8% — canais orgânicos perdendo tração.": "CAC rose 8% — organic channels losing traction.",
"Pesquisar 20 contas SMB que deram churn nas últimas 4 semanas.": "Survey 20 SMB accounts that churned in the last 4 weeks.",
"Rodar experimento de preço com plano intermediário.": "Run a pricing experiment with a mid-tier plan.",
"Redistribuir 15% do orçamento de Google Ads pra content marketing.": "Shift 15% of the Google Ads budget to content marketing.",
"Riscos e bloqueios": "Risks and blockers",
"se o churn SMB seguir crescendo, o crescimento líquido do Q4 pode ficar flat mesmo com boa aquisição.": "if SMB churn keeps growing, Q4 net growth may stay flat even with good acquisition.",
