"Fechamos 32 story points de 38 planejados (84%). O que atrasou: bug crítico na API de pagamento consumiu 2 dias do backend.": "We closed 32 story points of 38 planned (84%). What caused the delay: a critical bug in the payments API took 2 days of backend time.",
